parameters.toolDescription:
Use essa ferramenta sempre que o usuário demonstrar não querer mais receber mensagens de follow up.
Exemplos de mensagens demonstrando não querer receber mais follow ups:
- "Não tenho interesse, obrigado";
- "Não quero mais receber mensagens";
- "Me retire da lista de mensagens de vocês".

parameters.query:
-- Criação da tabela 'users'
CREATE TABLE public.users (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamp DEFAULT now() NOT NULL,
    name text,
    phone varchar,
    session_id varchar,
    last_message timestamp,
    fup boolean DEFAULT true,
    fup_number smallint DEFAULT 0,
    fup_sent timestamp,
    ai_response boolean DEFAULT true
);

-- Comentários descritivos
COMMENT ON TABLE public.users IS 'Tabela para armazenar informações de usuários autenticados e interações relacionadas.';
COMMENT ON COLUMN public.users.id IS 'Identificador único do registro.';
COMMENT ON COLUMN public.users.created_at IS 'Data de criação do registro.';
COMMENT ON COLUMN public.users.name IS 'Nome do usuário.';
COMMENT ON COLUMN public.users.phone IS 'Número de telefone do usuário.';
COMMENT ON COLUMN public.users.session_id IS 'Identificador da sessão de chat.';
COMMENT ON COLUMN public.users.last_message IS 'Data e hora da última mensagem.';
COMMENT ON COLUMN public.users.fup IS 'Indica se há follow-up pendente.';
COMMENT ON COLUMN public.users.fup_number IS 'Número de follow-ups realizados.';
COMMENT ON COLUMN public.users.fup_sent IS 'Data de envio do último follow-up.';
COMMENT ON COLUMN public.users.ai_response IS 'Indica se a última resposta foi gerada por IA.';

-- Ativar Row Level Security
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
